def get_endpoint_context(
    dependant: "Dependant", method: str, path: str
) -> Optional[Dict[str, Any]]:
    call = dependant.call
    if call is None:
        return None

    try:
        frame = inspect.getframeinfo(call)
        filepath = frame.filename
        lineno = frame.lineno
        func_name = call.__name__
    except Exception:
        return None

    return {
        "filepath": filepath,
        "lineno": lineno,
        "func_name": func_name,
        "method": method,
        "path": path,
    }


